'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var abs = require( '@stdlib/math/base/special/abs' );


// MAIN //

/**
* Performs LU factorization of a real tridiagonal matrix A of order n.
* A is represented by its three diagonals: dl (sub-diagonal), d (main), du (super-diagonal).
* This function computes the factorization A = L * U with partial pivoting.
*
* @param {Float64Array|number[]} dl - sub-diagonal array of length n-1 (will be overwritten with multipliers)
* @param {Float64Array|number[]} d - main diagonal array of length n (will be overwritten with U diagonal)
* @param {Float64Array|number[]} du - super-diagonal array of length n-1 (will be overwritten with U first super-diagonal)
* @throws {Error} If inputs are invalid.
* @returns {Object} result - An object with properties: dl, d, du, du2, ipiv, info
*
* @example
* var dl = [2.0, 3.0];
* var d = [4.0, 5.0, 6.0];
* var du = [1.0, 2.0];
* var out = dgttrf(dl, d, du);
* // returns { 'dl': [...], 'd': [...], 'du': [...], 'du2': [...], 'ipiv': [...], 'info': 0 }
*/
function dgttrf( dl, d, du ) {
	var info = 0;
	var ipiv;
	var temp;
	var fact;
	var du2;
	var n = d.length;
	var i;

	if ( n < 1 ) {
		throw new Error( 'Invalid input: matrix order n must be at least 1' );
	}
	if ( dl.length !== n-1 || du.length !== n-1 ) {
		throw new Error( 'Invalid input: dl and du must have lengths n-1' );
	}
	du2 = (n > 2) ? new Float64Array( n-2 ) : new Float64Array(0);
	ipiv = new Int32Array( n );

	// Check for NaN in input arrays, set info to first NaN index (1-based) like LAPACK
	for ( i = 0; i < dl.length; i++ ) {
		if ( dl[i] !== dl[i] ) {
			info = i+1;
			break;
		}
	}
	if ( info === 0 ) {
		for (i = 0; i < d.length; i++) {
			if ( d[i] !== d[i] ) {
				info = i+1;
				break;
			}
		}
	}
	if ( info === 0 ) {
		for ( i = 0; i < du.length; i++ ) {
			if ( du[i] !== du[i] ) {
				info = i+1;
				break;
			}
		}
	}
	if ( info !== 0 ) {
		return {
			'dl': dl,
			'd': d,
			'du': du,
			'du2': du2,
			'ipiv': ipiv,
			'info': info
		};
	}

	for ( i = 0; i < n; i++ ) {
		ipiv[i] = i;
	}

	if ( n === 1 ) {
		if ( d[0] === 0.0 || d[0] !== d[0] ) {
			info = 1;
		}
		return {
			'dl': dl,
			'd': d,
			'du': du,
			'du2': du2,
			'ipiv': ipiv,
			'info': info
		};
	}
	if ( n === 2 ) {
		// Only one sub/super-diagonal
		if ( abs(d[0]) >= abs(dl[0]) ) {
			if ( d[0] === 0.0 || d[0] !== d[0] ) {
				info = 1;
			}
			fact = dl[0] / d[0];
			dl[0] = fact;
			d[1] -= fact * du[0];
			ipiv[0] = 0;
			ipiv[1] = 1;
		} else {
			if ( dl[0] === 0.0 || dl[0] !== dl[0] ) {
				info = 1;
			}
			fact = d[0] / dl[0];
			temp = d[0];
			d[0] = dl[0];
			dl[0] = fact;
			temp = du[0];
			du[0] = d[1];
			d[1] = temp - (fact * d[1]);
			ipiv[0] = 1;
			ipiv[1] = 1;
		}
		if ( d[1] === 0.0 || d[1] !== d[1] ) {
			if (info === 0) {
				info = 2;
			}
		}
		return {
			'dl': dl,
			'd': d,
			'du': du,
			'du2': du2,
			'ipiv': ipiv,
			'info': info
		};
	}
	// n >= 3
	for ( i = 0; i < n-2; i++ ) {
		if ( abs( d[i] ) >= abs( dl[i] ) ) {
			if ( d[i] === 0.0 || d[i] !== d[i] ) {
				if ( info === 0 ) {
					info = i+1;
				}
				break;
			}
			fact = dl[i] / d[i];
			dl[i] = fact;
			d[i+1] -= (fact * du[i]);
			du2[i] = 0.0;
		} else if ( dl[i] === 0.0 || dl[i] !== dl[i] ) {
			if ( info === 0 ) {
				info = i+1;
			}
			break;
		} else {
			fact = d[i] / dl[i];
			temp = d[i];
			d[i] = dl[i];
			dl[i] = fact;
			temp = du[i];
			du[i] = d[i+1];
			d[i+1] = temp - (fact * d[i+1]);
			du2[i] = du[i+1];
			du[i+1] = -(fact * du[i+1]);
			ipiv[i] = i+1;
		}
	}
	// Last 2 rows
	i = n-2;
	if ( info === 0 ) {
		if ( abs( d[i] ) >= abs( dl[i] ) ) {
			if ( d[i] === 0.0 || d[i] !== d[i] ) {
				info = i+1;
			} else {
				fact = dl[i] / d[i];
				dl[i] = fact;
				d[i+1] -= (fact * du[i]);
			}
		} else if ( dl[i] === 0.0 || dl[i] !== dl[i] ) {
			info = i+1;
		} else {
			fact = d[i] / dl[i];
			temp = d[i];
			d[i] = dl[i];
			dl[i] = fact;
			temp = du[i];
			du[i] = d[i+1];
			d[i+1] = temp - (fact * d[i+1]);
			ipiv[i] = i+1;
		}
		if ( d[n-1] === 0.0 || d[n-1] !== d[n-1] ) {
			if ( info === 0 ) {
				info = n;
			}
		}
	}
	return {
		'dl': dl,
		'd': d,
		'du': du,
		'du2': du2,
		'ipiv': ipiv,
		'info': info
	};
}


// EXPORTS //

module.exports = dgttrf;
